mapper.select:
SELECT FLOOR, TILE_NO, TILE_TYPE FROM TBOT_S5_TILE_MASTER
WHERE FLOOR = #{floor}
ORDER BY TILE_NO

SELECT FLOOR, TILE_NO, TILE_TYPE FROM TBOT_S5_USER_TILE_MASTER
WHERE USER_NAME = #{userName} AND FLOOR = #{floor}
ORDER BY TILE_NO

SELECT * FROM (
    SELECT COMPANION_ID FROM TBOT_S5_USER_COMPANION WHERE IMAGE_URL IS NULL ORDER BY COMPANION_ID
) WHERE ROWNUM <= #{limit}

mapper.update:
UPDATE TBOT_S5_USER_COMPANION
SET CUR_HP_VALUE = #{curHpValue}, CUR_HP_EXT = #{curHpExt}
WHERE COMPANION_ID = #{companionId}

UPDATE TBOT_S5_USER_COMPANION
SET PARTY_SLOT = #{partySlot, jdbcType=NUMERIC}
WHERE COMPANION_ID = #{companionId}

UPDATE TBOT_S5_USER_EQUIP
SET EQUIPPED_COMPANION_ID = #{equippedCompanionId, jdbcType=NUMERIC}
WHERE EQUIP_ID = #{equipId}

UPDATE TBOT_S5_USER_PROGRESS
SET COMPANION_VOUCHER = NVL(COMPANION_VOUCHER, 0) + #{companionQty},
    EQUIP_VOUCHER = NVL(EQUIP_VOUCHER, 0) + #{equipQty}

mapper.select:
SELECT NVL(MAX(CNT), 0) FROM (
    SELECT COUNT(*) CNT FROM TBOT_S5_USER_ACH GROUP BY USER_NAME
)

SELECT NVL(MAX(CNT), 0) FROM (
    SELECT COUNT(*) CNT FROM TBOT_S5_USER_FLOOR_BEST WHERE FULLY_EXPLORED_YN = 'Y' GROUP BY USER_NAME
)

SELECT NVL(MAX(CNT), 0) FROM (
    SELECT COUNT(*) CNT FROM TBOT_S5_USER_COMPANION GROUP BY USER_NAME
)

SELECT NVL(MAX(CNT), 0) FROM (
    SELECT COUNT(*) CNT FROM TBOT_S5_USER_EQUIP GROUP BY USER_NAME
)
